    #[test]
    fn replace_prompt_shortcuts_are_unambiguous_and_press_only() {
        use crossterm::event::{KeyCode, KeyEvent, KeyEventKind, KeyModifiers};

        assert_eq!(
            search_field_for_key(&KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)),
            Some(SearchField::Replacement)
        );
        assert_eq!(
            search_field_for_key(&KeyEvent::new(KeyCode::BackTab, KeyModifiers::SHIFT)),
            Some(SearchField::Query)
        );
        assert!(is_replace_all(&KeyEvent::new(
            KeyCode::Enter,
            KeyModifiers::ALT
        )));
        assert!(is_replace_all(&KeyEvent::new(
            KeyCode::Enter,
            KeyModifiers::CONTROL
        )));

        for kind in [KeyEventKind::Repeat, KeyEventKind::Release] {
            assert_eq!(
                search_field_for_key(&KeyEvent::new_with_kind(
                    KeyCode::Tab,
                    KeyModifiers::NONE,
                    kind,
                )),
                None
            );
            assert!(!is_replace_all(&KeyEvent::new_with_kind(
                KeyCode::Enter,
                KeyModifiers::ALT,
                kind,
            )));
        }
        assert!(!is_replace_all(&KeyEvent::new(
            KeyCode::Enter,
            KeyModifiers::NONE
        )));
        assert!(!is_replace_all(&KeyEvent::new(
            KeyCode::Enter,
            KeyModifiers::SHIFT
        )));
    }

    #[test]
    fn another_input_action_resets_discard_confirmation() {
        use crossterm::event::{
            KeyCode, KeyEvent, KeyEventKind, KeyModifiers, MouseButton, MouseEvent, MouseEventKind,
        };

        let quit = TerminalEvent::Key(KeyEvent::new(KeyCode::Char('q'), KeyModifiers::CONTROL));
        let other_press =
            TerminalEvent::Key(KeyEvent::new(KeyCode::Char('c'), KeyModifiers::CONTROL));
        let other_repeat = TerminalEvent::Key(KeyEvent::new_with_kind(
            KeyCode::Char('c'),
            KeyModifiers::CONTROL,
            KeyEventKind::Repeat,
        ));

        assert!(!resets_confirmation(&quit, input::is_quit));
        assert!(resets_confirmation(&other_press, input::is_quit));
        assert!(!resets_confirmation(&other_repeat, input::is_quit));
        assert!(resets_confirmation(
            &TerminalEvent::Paste("text".to_owned()),
            input::is_quit
        ));
        assert!(resets_confirmation(
            &TerminalEvent::MouseScroll(ScrollDirection::Down),
            input::is_quit
        ));
        assert!(resets_confirmation(
            &TerminalEvent::Mouse(MouseEvent {
                kind: MouseEventKind::Down(MouseButton::Left),
                column: 3,
                row: 2,
                modifiers: KeyModifiers::NONE,
            }),
            input::is_quit
        ));
        assert!(!resets_confirmation(&TerminalEvent::Redraw, input::is_quit));
    }

    #[test]
    fn terminal_mouse_clicks_track_cell_timeout_and_cycle_granularity() {
        let mut tracker = TerminalMouseClickTracker::default();
        let start = Instant::now();

        assert_eq!(tracker.register(12, 7, start), 1);
        assert_eq!(
            TerminalMouseSelectionGranularity::from_click_count(1),
            TerminalMouseSelectionGranularity::Character
        );
        assert_eq!(
            tracker.register(12, 7, start + Duration::from_millis(100)),
            2
        );
        assert_eq!(
            TerminalMouseSelectionGranularity::from_click_count(2),
            TerminalMouseSelectionGranularity::Word
        );
        assert_eq!(
            tracker.register(12, 7, start + Duration::from_millis(200)),
            3
        );
        assert_eq!(
            TerminalMouseSelectionGranularity::from_click_count(3),
            TerminalMouseSelectionGranularity::Line
        );
        assert_eq!(
            tracker.register(12, 7, start + Duration::from_millis(300)),
            1,
            "a fourth terminal click starts a new gesture cycle"
        );
        assert_eq!(
            tracker.register(13, 7, start + Duration::from_millis(350)),
            1,
            "moving to another cell resets the sequence"
        );
        assert_eq!(
            tracker.register(13, 7, start + Duration::from_millis(851)),
            1,
            "a click after the multi-click interval starts a new sequence"
        );
    }

